    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xDC991D3D830B411FULL + 0xF980C607C1E0BAE9ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xE73BF60134D05F8DULL + 0x977DD6C022526116ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xED3D9CFF0CA59189ULL + 0xA64DD05F68C1EDD7ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xD9CFF754569B1927ULL + 0xEC06E5DEEA914AFFULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xEF4C0FA6F1036ED9ULL + 0xC636DC4895C4AE5DULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0x9B367B7BE480FED7ULL + 0xEEF4CA3AAE0D4335ULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0x99E09C822799EF3DULL + 0xB11FAD1EB306BC05ULL);
