    const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xB6C00E1958F3123BULL + 0xB9F425C942BFB503ULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xE5C3C211DFAE9FB5ULL + 0xA76D80C7A85CB145ULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0xD72E6BFB0E6E89B9ULL + 0xCEADED6253121744ULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseA(pNonce * 0xD8F5F2495F86ACDBULL + 0xDF56F04A107B1E04ULL);
    const std::uint64_t aNonceWordO = TwistMix64::DiffuseC(pNonce * 0xB93EB8599F8D3A81ULL + 0xB4641C5CDCCF970CULL);
    const std::uint64_t aNonceWordP = TwistMix64::DiffuseB(pNonce * 0x9419443F5DA41BCDULL + 0xEC62E34DB2C44CF0ULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
