            aOrbiterG = (aWandererK + RotL64(aIngress, 27U)) + 0xD089DCDD2D22C857ULL;
            aOrbiterE = ((aWandererG + RotL64(aScatter, 35U)) + RotL64(aCarry, 27U)) + 0x1817773C54C2D569ULL;
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 3U)) + 0xB45A117851838AFEULL) + aNonceWordF;
            aOrbiterJ = ((aWandererJ + RotL64(aCross, 5U)) + 0x4725EC7E1F1F41A2ULL) + aOASaltD[(((511U - aIndex) + 215U)) & S_SALT1];
            aOrbiterH = (((aWandererA + RotL64(aIngress, 19U)) + RotL64(aCarry, 47U)) + 0x7105E4A77AEDF907ULL) + aNonceWordP;
            aOrbiterI = (((aWandererF + RotL64(aScatter, 54U)) + 0xE97AAE4D6866B2A3ULL) + aOASaltH[(((511U - aIndex) + 207U)) & S_SALT1]) + aNonceWordL;
            aOrbiterB = ((aWandererC + RotL64(aPrevious, 41U)) + 0xE55E5F2A2C75367EULL) + aOASaltF[((aIndex + 368U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xDD57E458F76C4F6AULL;
