            aOrbiterI = RotL64((aOrbiterI * 0xE0A4174CA4C05687ULL), 41U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0xF732D407A579F7ABULL) + aOUSaltF[(((511U - aIndex) + 39U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterB) ^ 0x02BBD797A1DC9B77ULL) ^ aNonceWordB;
