            aIngress ^= (RotL64(aHeartLaneD[((aIndex + 3755U)) & S_BLOCK1], 35U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 4753U)) & S_BLOCK1], 4U));
