            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0x5028F916D93F2F10ULL) + aOUSaltC[(((511U - aIndex) + 491U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x3569A1C2D08CF24CULL) ^ aOUSaltB[(((511U - aIndex) + 339U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x9D15D384D1312C21ULL), 23U);
            //
