            aWandererF = aWandererF ^ ((((RotL64(aCross, 29U) + RotL64(aOrbiterK, 13U)) + aOrbiterJ) + aNonceWordG) + aWUSaltC[((aIndex + 421U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aIngress, 21U) + aOrbiterH) + RotL64(aOrbiterD, 41U));
