            aWandererI = aWandererI ^ ((((RotL64(aCross, 53U) + aOrbiterD) + RotL64(aOrbiterI, 35U)) + RotL64(aCarry, 43U)) + aWUSaltG[((aIndex + 420U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aIngress, 51U) + aOrbiterE) + RotL64(aOrbiterB, 56U)) + aNonceWordI);
            aWandererG = aWandererG ^ ((((RotL64(aScatter, 41U) + RotL64(aOrbiterG, 23U)) + aOrbiterF) + aNonceWordK) + aWUSaltD[((aIndex + 265U)) & S_SALT1]);
            aWandererC = aWandererC + ((RotL64(aPrevious, 56U) + RotL64(aOrbiterJ, 5U)) + aOrbiterE);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererE, 28U));
